## Why This Is Asked

Duplicate values are common in real-world data sets. Traditional 2-way quicksort performs poorly with many duplicates, leading to unnecessary comparisons and degraded performance. 3-way partitioning addresses this by grouping equal elements together, significantly reducing the algorithm's work.

## Key Concepts

- **3-way partitioning (Dutch national flag algorithm)**: Separates array into < pivot, == pivot, and > pivot regions
- **Randomized pivot selection**: Prevents worst-case O(n²) scenarios on already sorted or adversarial input
- **In-place sorting**: Operates with O(1) additional space, using only O(log n) expected stack depth
- **Performance optimization**: Reduces comparisons from O(n log n) to O(n) when many duplicates exist

## Code Example

```javascript
function quicksort3(a, lo = 0, hi = a.length - 1) {
  if (lo >= hi) return;

  // Random pivot selection
  const pivot = a[Math.floor(Math.random() * (hi - lo + 1)) + lo];
  let lt = lo, i = lo, gt = hi;

  // 3-way partitioning
  while (i <= gt) {
    if (a[i] < pivot) {
      [a[lt], a[i]] = [a[i], a[lt]];
      lt++;
      i++;
    } else if (a[i] > pivot) {
      [a[i], a[gt]] = [a[gt], a[i]];
      gt--;
    } else {
      i++; // a[i] === pivot
    }
  }

  // Recursively sort subarrays
  quicksort3(a, lo, lt - 1);
  quicksort3(a, gt + 1, hi);
}
```

## Partitioning Strategy

The algorithm maintains three regions during partitioning:
- `[lo, lt-1]`: elements < pivot
- `[lt, gt]`: elements === pivot (being processed)
- `[gt+1, hi]`: elements > pivot

As we iterate, elements are swapped into their appropriate region, with equal elements naturally forming the middle section that needs no further processing.

## Why This Is Asked
Tests ability to frame a sign-assignment problem as a DP and implement both memoization and tabulation, a common interview pattern.

## Key Concepts
- DP state reduction to subset sum
- Space optimization with a 1D array
- Memoization vs bottom-up trade-offs

## Code Example
```javascript
// Tabulation and Memo versions
function countTargetSumTab(nums, S) {
  const total = nums.reduce((a,b)=>a+b,0);
  if (Math.abs(S) > total || (total+S)%2 !== 0) return 0;
  const target = (total+S)/2;
  const dp = Array(target+1).fill(0);
  dp[0] = 1;
  for (const n of nums) {
    for (let t = target; t >= n; t--) dp[t] += dp[t-n];
  }
  return dp[target];
}

function countTargetSumMemo(nums, S) {
  const total = nums.reduce((a,b)=>a+b,0);
  if (Math.abs(S) > total || (total+S)%2 !== 0) return 0;
  const target = (total+S)/2;
  const memo = new Map();
  function dfs(i, sum){
    if (sum > target) return 0;
    if (i === nums.length) return sum === target ? 1 : 0;
    const key = i+':'+sum;
    if (memo.has(key)) return memo.get(key);
    const res = dfs(i+1, sum+nums[i]) + dfs(i+1, sum);
    memo.set(key, res);
    return res;
  }
  return dfs(0,0);
}
```

## Why This Is Asked

Tests practical algorithm design that blends classic sorts and data-structure choices. It assesses the ability to identify run structures, select appropriate sorting strategies by run size, and implement an efficient, stable k-way merge.

## Key Concepts

- Natural monotone runs detection in O(n)
- Insertion sort for small ranges; mergesort for larger ranges
- K-way merge with a min-heap and lazy advancement
- Stability guarantees and complexity trade-offs

## Code Example

```javascript
function hybridSort(a){
  const n=a.length; 
  // 1) detect monotone runs
  const runs=[]; let i=0;
  while(i<n){
    let j=i+1;
    while(j<n && a[j-1] <= a[j]) j++;
    runs.push([i,j]);
    i=j;
  }
  // 2) sort each run
  for(const [l,r] of runs){
    if(r-l <= 32) insertionSort(a,l,r);
    else mergeSort(a,l,r);
  }
  // 3) k-way merge using a min-heap
  const heap=new MinHeap((x,y)=> x.val<y.val);
  for(let idx=0; idx<runs.length; idx++){
    const [l,r]=runs[idx];
    if(l<r) heap.push({val:a[l], pos:l, runIdx:idx});
  }
  const out=new Array(n); let k=0;
  while(!heap.isEmpty()){
    const {val,pos,runIdx}=heap.pop();
    out[k++]=val;
    const [l,r]=runs[runIdx];
    const next=pos+1;
    if(next<r) heap.push({val:a[next], pos:next, runIdx});
  }
  for(let t=0;t<n;t++) a[t]=out[t];
}

function insertionSort(a,l,r){
  for(let i=l+1;i<r;i++){
    const key=a[i]; let j=i-1;
    while(j>=l && a[j]>key){ a[j+1]=a[j]; j--; }
    a[j+1]=key;
  }
}

function mergeSort(a,l,r){
  if(r-l<=1) return;
  const m=(l+r)>>1;
  mergeSort(a,l,m); mergeSort(a,m,r);
  // merge [l,m) and [m,r)
  const left=a.slice(l,m); let i=0, j=m, t=l;
  while(i<left.length && j<r) a[t++]= left[i++]<a[j]? left[i-1]: a[j++];
  while(i<left.length) a[t++]=left[i++];
  while(j<r) a[t++]=a[j++];
}

class MinHeap{
  constructor(cmp){ this.a=[]; this.cmp=cmp||((x,y)=> x<y); }
  push(x){ this.a.push(x); this.bubbleUp(this.a.length-1); }
  pop(){ if(this.a.length===0) return null; const top=this.a[0]; const end=this.a.pop(); if(this.a.length){ this.a[0]=end; this.sinkDown(0); } return top; }
  isEmpty(){ return this.a.length===0; }
  bubbleUp(n){ const a=this.a[n]; while(n>0){ const p=(n-1)>>1; if(this.cmp(a, this.a[p])){ this.a[n]=this.a[p]; n=p; } else break; } this.a[n]=a; }
  sinkDown(n){ const length=this.a.length; const element=this.a[n]; while(true){ let child2=(n+1)*2, child1=child2-1; let swap=null; if(child1<length){ if(this.cmp(this.a[child1], element)) swap=child1; } if(child2<length){ if(this.cmp(this.a[child2], swap===null?element:this.a[child1])) swap=child2; } if(swap===null) break; this.a[n]=this.a[swap]; n=swap; } this.a[n]=element; }
}
```

